         padding: clamp(1.25rem, 3vw, 2rem);
         box-shadow: 0 24px 60px var(--shadow);
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         color: var(--accent);
         font-size: 0.875rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(1.8rem, 4vw, 2.5rem);
         line-height: 1.15;
       }

       .intro {
         margin: 0.75rem 0 0;
         max-width: 60ch;
         color: var(--muted);
