       input {
         width: 100%;
         min-width: 0;
         border: 1px solid var(--border);
         border-radius: 0.9rem;
         padding: 0.95rem 1rem;
         background: var(--field);
         color: var(--text);
         font: inherit;
         transition: border-color 0.15s ease, background-color 0.15s ease;
       }

       input::placeholder {
         color: var(--muted);
       }

       input:hover {
         border-color: var(--accent);
