       @media (max-width: 30rem) {
         main {
           padding-top: 4rem;
         }

         .support-card {
           border-radius: 1rem;
         }

         .actions {
           justify-content: stretch;
         }

         button {
           width: 100%;
         }
       }

       @media (forced-colors: active) {
         :root {
           --bg: Canvas;
           --panel: Canvas;
           --panel-2: Canvas;
           --border: ButtonBorder;
           --text: CanvasText;
           --muted: CanvasText;
           --accent: LinkText;
           --accent-strong: LinkText;
           --error: CanvasText;
           --error-bg: Canvas;
           --field: Canvas;
           --focus: Highlight;
         }

         .support-card,
         input,
         button {
           forced-color-adjust: auto;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <main id="main"></main>

     <script>
       const escapeHtml = (value) =>
         String(value)
           .replaceAll("&", "&amp;")
           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;")
           .replaceAll('"', "&quot;");

       const field = (id, label, { required = false, type = "text", autocomplete = "", helper = "" } = {}) => `
         <div class="form-field">
           <label for="${id}">
             ${escapeHtml(label)}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ""}
           </label>
           <input
             id="${id}"
             name="${id}"
             type="${type}"
             ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
             ${required ? "required aria-required=\"true\"" : ""}
             aria-describedby="${id}-hint ${id}-error"
             aria-invalid="false"
           />
           <span class="field-hint" id="${id}-hint">${escapeHtml(helper)}</span>
           <div class="field-error" id="${id}-error" aria-live="polite"></div>
         </div>
       `;

       const app = () => `
         <section class="support-card" aria-labelledby="page-title">
           <p class="eyebrow">Support</p>
           <h1 id="page-title">Contact the support team</h1>
           <p class="intro">Send a request and include the best ways for us to reach you.</p>
           <form id="contact-form" novalidate>
             ${field("fullName", "Full name", {
               required: true,
               autocomplete: "name",
             })}
             ${field("emailAddress", "Email address", {
               required: true,
               type: "email",
               autocomplete: "email",
             })}
             ${field("phoneNumber", "Phone number", {
               type: "tel",
               autocomplete: "tel",
               helper: "Optional. Use a format like +1 555 123 4567 or 555-123-4567.",
             })}
             <div class="actions">
               <button type="submit">Submit request</button>
             </div>
             <p class="form-status" id="form-status" role="status" aria-live="polite"></p>
           </form>
         </section>
       `;

       const root = document.getElementById("main");
       root.innerHTML = app();

       const form = document.getElementById("contact-form");
       const status = document.getElementById("form-status");
       const fields = {
         fullName: document.getElementById("fullName"),
         emailAddress: document.getElementById("emailAddress"),
         phoneNumber: document.getElementById("phoneNumber"),
       };
       const errors = {
         fullName: document.getElementById("fullName-error"),
         emailAddress: document.getElementById("emailAddress-error"),
         phoneNumber: document.getElementById("phoneNumber-error"),
       };

       const validators = {
         fullName(value) {
           return value.trim() ? "" : "Please enter your full name.";
         },
         emailAddress(value) {
           const trimmed = value.trim();
           if (!trimmed) {
             return "Please enter your email address.";
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           return emailPattern.test(trimmed) ? "" : "Enter a valid email address, such as name@example.com.";
         },
         phoneNumber(value) {
           const trimmed = value.trim();
           if (!trimmed) {
             return "";
           }

           const allowedPattern = /^[0-9+\-\s().]{7,}$/;
           const digitCount = (trimmed.match(/\d/g) || []).length;
           return allowedPattern.test(trimmed) && digitCount >= 7
             ? ""
             : "Enter a valid phone number, such as +1 555 123 4567.";
         },
       };

       function setFieldState(name, message) {
         const input = fields[name];
         const error = errors[name];
         const invalid = Boolean(message);

         input.setAttribute("aria-invalid", invalid ? "true" : "false");
         error.textContent = message;
       }

       function validateField(name) {
         const message = validators[name](fields[name].value);
         setFieldState(name, message);
         return !message;
       }

       Object.entries(fields).forEach(([name, input]) => {
         input.addEventListener("blur", () => validateField(name));
         input.addEventListener("input", () => {
           if (errors[name].textContent) {
             validateField(name);
           }
           status.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const order = ["fullName", "emailAddress", "phoneNumber"];
         const firstInvalid = order.find((name) => !validateField(name));

         if (firstInvalid) {
           status.textContent = "Please fix the highlighted fields before submitting.";
           fields[firstInvalid].focus();
           return;
         }

         status.textContent = "Your support request is ready to be submitted.";
       });
     </script>
   </body>
 </html>

